@Test
public void testGenerateListExample() {
    // generates a collection of Floats from 0 (inclusive) to 10 (exclusive)
    {
        List<? super Float> list = (List<? super Float>) (IteratorToGeneratorAdapter.adapt(Ranges.floatRange(0, 10)).to(new ArrayList<Float>()));
        for (int i = 0; i < 10; i++) {
            assertEquals(Float.valueOf(i), list.get(i));
        }
    }
    // generates a collection of Floats from 10 (inclusive) to 0 (exclusive)
    {
        List<? super Float> list = (List<? super Float>) (IteratorToGeneratorAdapter.adapt(Ranges.floatRange(10, 0)).to(new ArrayList<Float>()));
        for (int i = 10; i > 0; i--) {
            assertEquals(Float.valueOf(i), list.get(10 - i));
        }
    }
}

@Test
public void testStepChecking() {
    {
        // step of 0 is ok when range is empty
        Ranges.floatRange(2, 2, 0);
    }
    {
        // positive step is ok when range is
        Ranges.floatRange(2, 2, 1);
        // empty
    }
    {
        // negative step is ok when range is
        Ranges.floatRange(2, 2, -1);
        // empty
    }
    {
        // big steps are ok
        Ranges.floatRange(0, 1, 10);
    }
    {
        // big steps are ok
        Ranges.floatRange(1, 0, -10);
    }
    try {
        Ranges.floatRange(0, 1, 0);
        fail("Expected IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // expected
    }
    try {
        Ranges.floatRange(0, 1, -1);
        fail("Expected IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // expected
    }
    try {
        Ranges.floatRange(0, -1, 1);
        fail("Expected IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // expected
    }
}

