            }
            return total;
        }
    });
    assertEquals(expected, total);
    expected = 55.0f;
    total = IteratorToGeneratorAdapter.adapt(descFloatRange).to(new Function<Generator<? extends Float>, Float>() {

        public Float evaluate(Generator<? extends Float> obj) {
